set-variable.value:
@{
            try {
                var body = context.Request.Body?.As<JObject>(preserveContent: true);
                return body?["method"]?.ToString() ?? string.Empty;
            } catch (Exception) { return string.Empty; }
        }

@{
            try {
                var body = context.Request.Body?.As<JObject>(preserveContent: true);
                return body?["params"]?["name"]?.ToString() ?? string.Empty;
            } catch (Exception) { return string.Empty; }
        }

when.condition:
@{
                        var requested = (string)context.Variables["mcpToolName"];
                        var allowed = new [] { "list_items", "search_items", "get_item", "check_availability", "check_availability_batch", "list_records", "get_record", "create_record", "update_record" };
                        return string.IsNullOrWhiteSpace(requested) || !allowed.Contains(requested, StringComparer.OrdinalIgnoreCase);
                    }
